<template><section class="wb-panel" aria-label="清洗诊断与差异"><h3>{{cleanedRef ? '已保存的清洗差异' : '清洗诊断与样本预览'}}</h3><p class="wb-footnote">按真实来源行展示变化；原始资产保持不变。敏感字段会显示原始值，请在当前授权范围内复核。</p><button type="button" :disabled="busy || !sourceRef && !cleanedRef" @click="load(false)">{{busy ? '正在核对…' : cleanedRef ? '读取真实差异' : '预览清洗方案（不保存）'}}</button><p v-if="error" role="alert" class="wb-error">{{error}}</p><template v-if="page"><p>共 {{page.total}} 条变化。{{diagnosis ? `保留率 ${(100*diagnosis.retention_rate).toFixed(1)}%` : ''}}</p><table v-if="diagnosis" class="wb-table"><thead><tr><th>指标</th><th>处理前</th><th>处理后</th></tr></thead><tbody><tr v-for="metric in metrics" :key="metric.key"><td>{{metric.name}}</td><td>{{diagnosis.before[metric.key]}}</td><td>{{diagnosis.after[metric.key]}}</td></tr></tbody></table><article v-for="change in page.items" :key="change.source_row"><strong>来源第 {{change.source_row+1}} 行 · {{change.removed_by ? `删除：${change.removed_by}` : `输出第 ${(change.output_row||0)+1} 行`}}</strong><p>{{change.operations.join(' → ')}}</p><div class="difference"><pre>{{JSON.stringify(change.before,null,2)}}</pre><pre>{{change.after ? JSON.stringify(change.after,null,2) : '已删除'}}</pre></div></article><button v-if="page.next_cursor" type="button" :disabled="busy" @click="load(true)">更多逐行差异</button><button v-if="digest && !cleanedRef" type="button" :disabled="busy" @click="confirm">确认此来源版本与清洗方案</button><p v-if="confirmed" role="status">方案已确认；来源或参数更改后需重新确认。</p></template></section></template>
<script setup lang="ts">
import {ref,watch,onBeforeUnmount} from 'vue'
import {useAuthStore} from '@/stores/auth'
import {http} from '@/utils/request'
import type {ExpertOptions} from '@/api/lifecycle'
interface Diff {source_row:number;output_row?:number;before:unknown[];after?:unknown[];operations:string[];removed_by?:string}
interface Page {items:Diff[];next_cursor:string;total:number;columns:string[]}
interface Diagnosis {retention_rate:number;before:Record<string,number>;after:Record<string,number>}
const props=defineProps<{sourceRef?:string;cleanedRef?:string;options?:ExpertOptions}>(),emit=defineEmits<{confirmed:[string]}>()
const auth=useAuthStore(),busy=ref(false),error=ref(''),page=ref<Page>(),diagnosis=ref<Diagnosis>(),digest=ref(''),confirmed=ref(false)
const metrics=[{key:'row_count',name:'行数'},{key:'missing_cells',name:'缺失单元格'},{key:'duplicate_rows',name:'重复行'},{key:'sensitive_cells',name:'规则命中敏感单元格'}]
let epoch=0
watch(()=>`${auth.authEpoch}:${auth.user?.id}:${auth.currentTenant?.id}:${props.sourceRef}:${props.cleanedRef}:${JSON.stringify(props.options)}`,()=>{epoch++;busy.value=false;page.value=undefined;diagnosis.value=undefined;digest.value='';confirmed.value=false;error.value='';emit('confirmed','')})
onBeforeUnmount(()=>{epoch++})
function confirm(){confirmed.value=true;emit('confirmed',digest.value)}
async function load(append=false){if(busy.value)return;const own=epoch;busy.value=true;error.value='';try{const cursor=append?page.value?.next_cursor||'':'';let next:Page;if(props.cleanedRef){const [id,version]=props.cleanedRef.split(':');const r=await http.get<Page>(`/lifecycle/assets/${id}/cleaning-diff`,{params:{version,cursor}});if(own!==epoch)return;if(!r.data)throw new Error('差异不可用');next=r.data}else{const [id,version]=(props.sourceRef||'').split(':');const r=await http.post<{differences:Page;diagnostics:Diagnosis;plan_digest:string}>('/lifecycle/cleaning/preview',{input_ref:{asset_id:id,version:Number(version)},options:props.options||{},cursor});if(own!==epoch)return;if(!r.data)throw new Error('诊断不可用');next=r.data.differences;diagnosis.value=r.data.diagnostics;digest.value=r.data.plan_digest}page.value={...next,items:append?[...(page.value?.items||[]),...next.items]:next.items}}catch(e){if(own===epoch)error.value=e instanceof Error?e.message:'清洗诊断失败'}finally{if(own===epoch)busy.value=false}}
</script>
<style scoped>.difference{display:grid;grid-template-columns:1fr 1fr;gap:12px}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:var(--color-surface);padding:12px}article{border-bottom:1px solid var(--color-border);padding:16px 0}button{margin:8px 8px 8px 0}</style>
